function trim(s) {
  return s.trim();
}

function slugify(s) {
  return s
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

module.exports = { trim, slugify };

  assert.strictEqual(slugify('a!@#b'), 'a-b');
  assert.strictEqual(slugify('a_b'), 'a-b');
});

// Pins the ASCII-only reading of "alphanumeric": non-ASCII letters are
// dropped rather than preserved or transliterated.
test('slugify drops non-ASCII letters', () => {
  assert.strictEqual(slugify('Café'), 'caf');
  assert.strictEqual(slugify('naïve café'), 'na-ve-caf');
});

